# разделы документа
# ---------------------------------------------------------------------------

def шапка(doc, d):
    согл = d.get("соглашение") or {}
    номер = поле(согл, "номер", "Соглашение: номер")
    дата = поле(согл, "дата", "Соглашение: дата")
    пр = поле(d, "предприятие", "Реквизиты: предприятие")
    рцк = поле(d, "рцк", "Реквизиты: РЦК")
    параграф(doc, "Протокол выполнения мероприятий", bold=True, center=True,
             size=14, justify=False)
    параграф(
        doc,
        f"по Соглашению о сотрудничестве в целях реализации национального проекта "
        f"«Производительность труда», федерального и регионального проектов "
        f"«Адресная поддержка повышения производительности труда на предприятиях» "
        f"№{номер} от {дата} между {пр} и {рцк}",
        bold=True, center=True, size=12, justify=False)

    t = таблица(doc, 1, 2, границы=False)
    _снять_границы(t)
    место = поле(d, "место_подписания", "Место подписания")
    дата_пр = поле(d, "дата_протокола", "Дата протокола")
    ячейка(t.rows[0].cells[0], место, center=True)
    ячейка(t.rows[0].cells[1], дата_пр, center=True)


def преамбула(doc, d):
    пр = d.get("предприятие") or "___"
    рцк = d.get("рцк") or "___"
    дата = (d.get("соглашение") or {}).get("дата") or "___"
    период = d.get("период") or {}
    с = поле(период, "с", "Период реализации: с")
    по = поле(период, "по", "Период реализации: по")

    параграф(doc,
        f"Между {рцк} (далее – РЦК) и {пр} (далее – Предприятие) заключено Соглашение "
        f"о сотрудничестве в целях реализации национального, федерального и "
        f"регионального проектов повышения производительности труда от {дата} "
        f"(далее – Соглашение о сотрудничестве).")
    параграф(doc,
        f"В рамках реализации Соглашения о сотрудничестве в период с {с} по {по} "
        f"при поддержке РЦК на Предприятии были успешно реализованы мероприятия, "
        f"указанные в приложении № 1 к настоящему Протоколу.")

    поток = поле(d, "поток_ключевого_продукта",
                 "Поток ключевого продукта (пилотный поток)")
    параграф(doc,
        f"Выполненные мероприятия позволили достичь следующих результатов в потоке "
        f"ключевого продукта {поток}:")

    # Таблица показателей до/цель/факт
    показатели = d.get("показатели") or []
    if not показатели:
        НЕДОСТАЮЩИЕ.append("Показатели потока (до/цель/факт) — хотя бы одна строка")
        показатели = [{}]
    t = таблица(doc, 1 + len(показатели), 6)
    for j, h in enumerate(["№", "Показатель", "Ед. изм.", "До проекта", "Цель", "Факт"]):
        ячейка(t.rows[0].cells[j], h, bold=True, center=True)
    for i, pk in enumerate(показатели):
        r = t.rows[i + 1].cells
        ячейка(r[0], i + 1, center=True)
        ячейка(r[1], pk.get("показатель") or "___")
        ячейка(r[2], pk.get("ед_изм") or "___", center=True)
        ячейка(r[3], fmt_число(pk.get("до")) if pk.get("до") is not None else "___", center=True)
        ячейка(r[4], fmt_число(pk.get("цель")) if pk.get("цель") is not None else "___", center=True)
        ячейка(r[5], fmt_число(pk.get("факт")) if pk.get("факт") is not None else "___", center=True)
    if any("___" in c.text for row in t.rows[1:] for c in row.cells):
        НЕДОСТАЮЩИЕ.append("Показатели потока: незаполненные ячейки (до/цель/факт)")

    параграф(doc,
        "В рамках реализации Соглашения предприятием открыты проекты и установлены "
        "следующие цели:")

    проекты = d.get("проекты_и_цели") or []
    if not проекты:
        НЕДОСТАЮЩИЕ.append("Открытые проекты и их цели (таблица после показателей)")
        проекты = [{}]
    t2 = таблица(doc, 1 + len(проекты), 6)
    заг = ["", "Проект по оптимизации продуктового потока/процесса",
           "ВПП", "Запасы", "Выработка", "Дополнительный показатель"]
    for j, h in enumerate(заг):
        ячейка(t2.rows[0].cells[j], h, bold=True, center=True)
    for i, pr in enumerate(проекты):
        r = t2.rows[i + 1].cells
        ячейка(r[0], i + 1, center=True)
        ячейка(r[1], pr.get("проект") or "___")
        цели = pr.get("цели") or {}
        for j, k in enumerate(["ВПП", "Запасы", "Выработка", "Дополнительный показатель"]):
            v = цели.get(k)
            ячейка(r[2 + j], fmt_число(v) if v not in (None, "") else "___")


def единое_мнение(doc, d):
    параграф(doc, "РЦК и Предприятие пришли к единому мнению, что:")
    цели = d.get("цели_пт") or {}
    баз = цели.get("к_базовому_году_пкт")
    тр3 = цели.get("к_3_году_пкт")
    if баз is None:
        баз = "___"
        НЕДОСТАЮЩИЕ.append("Цель ПТ: прирост к базовому году, %")
    if тр3 is None:
        тр3 = "___"
        НЕДОСТАЮЩИЕ.append("Цель ПТ: прирост к 3-му году, %")
    параграф(doc,
        f"Мероприятия, реализованные согласно приложению № 1, и запланированные "
        f"в рамках реализации дополнительных проектов, реализуемых предприятием "
        f"самостоятельно, в том числе указанных выше, позволят повысить "
        f"производительность труда на {баз}% к базовому году и на {тр3}% к 3 году "
        f"участия Предприятия в национальном проекте.")
    параграф(doc,
        "Мероприятия, реализованные согласно приложению № 1, позволили достичь "
        "целевого уровня развития производственной системы и создать поток-образец "
        "ключевого продукта (результаты оценки Предприятия по критериям развития "
        "производственной системы в приложении № 2).")
    ээ = d.get("ээ_руб_год")
    if ээ is None:
        НЕДОСТАЮЩИЕ.append("Экономический эффект (ЭЭ), руб/год")
        параграф(doc,
            "Экономический эффект от реализованных мероприятий составит ___ руб. в год.")
    else:
        параграф(doc,
            f"Экономический эффект от реализованных мероприятий составит {fmt_ээ(ээ)}.")
        # Фикс У-9: неположительный ЭЭ в подписном документе — не молчим,
        # документ всё равно формируется, но с явной пометкой.
        if isinstance(ээ, (int, float)) and not isinstance(ээ, bool) and ээ <= 0:
            параграф(doc,
                f"ВНИМАНИЕ: экономический эффект неположительный ({fmt_ээ(ээ)}). "
                "Проверьте входные данные перед подписанием протокола.", bold=True)
    практики = d.get("лучшие_практики") or []
    if практики:
        параграф(doc,
            "Мероприятия, реализованные согласно приложению № 1, позволили "
            "адаптировать под индивидуальные производственные условия и внедрить "
            "на базе Предприятия следующие лучшие практики (типовые решения):")
        for п in практики:
            параграф(doc, f"– {п}", justify=False, space_after=2)
    параграф(doc,
        "Предприятие дает согласие на использование РЦК информации, полученной "
        "в процессе реализации Мероприятий, для целей формирования и последующего "
        "тиражирования лучших практик повышения производительности труда.")

    # подписи
    подп = d.get("подписанты") or {}
    пп = подп.get("предприятие") or {}
    пр = подп.get("рцк") or {}
    for блок, имя in ((пп, "Подписант от Предприятия"), (пр, "Подписант от РЦК")):
        if not блок.get("должность") or not блок.get("фио"):
            НЕДОСТАЮЩИЕ.append(имя + ": должность и ФИО")
    параграф(doc, "")
    t = таблица(doc, 2, 2, границы=False)
    _снять_границы(t)
    ячейка(t.rows[0].cells[0],
           "от Предприятия:\n" + (пп.get("должность") or "___"), bold=True)
    ячейка(t.rows[0].cells[1], "от РЦК:\n" + (пр.get("должность") or "___"), bold=True)
    ячейка(t.rows[1].cells[0],
           "_____________________ /" + (пп.get("фио") or "___") + "/\nМ.П.")
    ячейка(t.rows[1].cells[1],
           "_____________________ /" + (пр.get("фио") or "___") + "/\nМ.П.")


def приложение_1(doc, d):
    doc.add_page_break()
    параграф(doc, "Приложение № 1", bold=True, center=True, justify=False)
    параграф(doc, "к Протоколу выполнения мероприятий", center=True, justify=False)
    дата = d.get("дата_протокола") or "___"
    параграф(doc, "от " + дата, center=True, justify=False)
    параграф(doc, "")

    результаты = d.get("мероприятия_результаты") or {}
    скел = СКЕЛЕТ["meropriyatiya"]
    t = таблица(doc, 1 + len(скел), 3)
    for j, h in enumerate(["№ п/п", "Наименование мероприятия", "Результат мероприятия"]):
        ячейка(t.rows[0].cells[j], h, bold=True, center=True)
    for i, (nomer, nazv, razdel) in enumerate(скел):
        r = t.rows[i + 1].cells
        if razdel:
            ячейка(r[0], nomer, bold=True)
            ячейка(r[1], nazv, bold=True, center=True)
            ячейка(r[2], "")
        else:
            ячейка(r[0], nomer)
            ячейка(r[1], nazv)
            ключ = nomer.rstrip(".")
            res = результаты.get(ключ)
            if res is None:
                res = "___"
                НЕДОСТАЮЩИЕ.append("Прил. № 1: результат мероприятия " + ключ)
            ячейка(r[2], res, center=True)


def приложение_2(doc, d):
    doc.add_page_break()
    параграф(doc, "Приложение № 2", bold=True, center=True, justify=False)
    параграф(doc, "к Протоколу выполнения мероприятий", center=True, justify=False)
    дата = d.get("дата_протокола") or "___"
    параграф(doc, "от " + дата, center=True, justify=False)
    параграф(doc, "Оценка уровня развития производственной системы Предприятия",
             bold=True, center=True, justify=False)
    for строка in [
        "Методика оценки:",
        "Оценка выполнения требований осуществляется последовательно от уровня «1» до уровня «3».",
        "Не допускается переходить к оценке следующего уровня при невыполнении требований предыдущего уровня частично или полностью.",
        "Например:",
        "Если требования уровня «2» содержат два условия, одно из которых не выполняется, то данное направление развития оценивается в 1 балл (при полном выполнении требований уровня «1»).",
        "Если требования уровня «3» содержат три условия, одно из которых не выполняется, то данное направление развития оценивается в 2 балла (при полном выполнении требований уровня «1» и «2»).",
        "Числовое значение уровня соответствия (1, 2 или 3) является оценкой в баллах данного направления развития.",
        "Баллы по всем направлениям развития суммируются в итоговую оценку.",
        "Целевой уровень развития производственной системы признается достигнутым при достижении итоговой оценки не менее 21 балла.",
    ]:
        параграф(doc, строка, size=10, space_after=2)

    баллы = (d.get("чеклист") or {}).get("баллы") or {}
    # Ред. v1.1 (фикс Н6): по-требовательный режим — если во входе есть
    # чеклист.оценки {номер: {"оценка": ..., "комментарий": ...}}, таблица
    # расширяется колонками «Оценка требования» и «Комментарий» (форма 132×7).
    # Без оценок рендер байт-в-байт прежний (режим «только баллы», 90×5).
    оценки = (d.get("чеклист") or {}).get("оценки") or {}
    напрявления = СКЕЛЕТ["napravleniya"]
    требования = СКЕЛЕТ["trebovaniya"]

    по_напр = {}
    for napr, nomer, tekst in требования:
        по_напр.setdefault(napr, []).append((nomer, tekst))

    итого = 0
    недостаёт_баллов = False
    ncol = 7 if оценки else 5
    заголовки = ["№", "Направление развития производственной системы",
                 "№ требования", "Требование производственной системы"]
    if оценки:
        заголовки += ["Оценка требования", "Комментарий"]
    заголовки += ["Оценка критерия, балл"]
    t = таблица(doc, 1 + len(требования) + 2, ncol)
    for j, h in enumerate(заголовки):
        ячейка(t.rows[0].cells[j], h, bold=True, center=True, size=9)
    ri = 1
    for ni, napr in enumerate(напрявления, start=1):
        б = баллы.get(str(ni), баллы.get(ni))
        if б is None:
            б_txt = "___"
            недостаёт_баллов = True
            НЕДОСТАЮЩИЕ.append("Прил. № 2: балл направления %d «%s» (чек-лист)" % (ni, napr))
        else:
            б = int(б)
            if not 0 <= б <= 3:
                raise ValueError("Направление %d: балл %d вне диапазона 0–3" % (ni, б))
            итого += б
            б_txt = str(б)
        for ki, (nomer, tekst) in enumerate(по_напр.get(napr, [])):
            r = t.rows[ri].cells
            ячейка(r[0], ni if ki == 0 else "", size=9, center=True)
            ячейка(r[1], napr if ki == 0 else "", size=9)
            ячейка(r[2], nomer, size=9, center=True)
            ячейка(r[3], tekst, size=9)
            col = 4
            if оценки:
                о = оценки.get(nomer.rstrip(".")) or {}
                оц = о.get("оценка")
                if not оц:
                    оц = "___"
                    НЕДОСТАЮЩИЕ.append("Прил. № 2: оценка требования " + nomer)
                ячейка(r[4], оц, size=9, center=True)
                ячейка(r[5], о.get("комментарий") or "", size=9)
                col = 6
            ячейка(r[col], б_txt if ki == 0 else "", size=9, center=True, bold=True)
            ri += 1
    r = t.rows[ri].cells
    ячейка(r[1], "Итого, баллов:", bold=True)
    ячейка(r[ncol - 1], "___" if недостаёт_баллов else str(итого), bold=True, center=True)
    ri += 1
    if недостаёт_баллов:
        вывод = ("Вывод: итоговая оценка не сформирована — заполнены не все "
                 "направления (см. перечень полей, требующих заполнения).")
    elif итого >= ПОРОГ_БАЛЛОВ:
        вывод = ("Вывод: Предприятие достигло целевого уровня развития "
                 "производственной системы.")
    else:
        вывод = ("Вывод: Предприятие не достигло целевого уровня развития "
                 "производственной системы.")
    r = t.rows[ri].cells
    ячейка(r[1], вывод, bold=True)
    return итого, недостаёт_баллов


def раздел_домерить(doc):
    if not НЕДОСТАЮЩИЕ:
        return
    doc.add_page_break()
    параграф(doc, "Поля, требующие заполнения («домерить»)", bold=True, size=12,
             justify=False)
    уник = []
    for м in НЕДОСТАЮЩИЕ:
        if м not in уник:
            уник.append(м)
    for м in уник:
        параграф(doc, "– " + м, justify=False, space_after=2, size=10)


# ---------------------------------------------------------------------------
# сборка
# ---------------------------------------------------------------------------

def сгенерировать(данные, путь_выход):
    global НЕДОСТАЮЩИЕ
    НЕДОСТАЮЩИЕ = []
    if not isinstance(данные, dict):
        raise ValueError("Корень вход-JSON должен быть объектом")

    doc = Document()
    стиль = doc.styles["Normal"]
    стиль.font.name = "Times New Roman"
    стиль.font.size = Pt(11)
    for sec in doc.sections:
        sec.left_margin = Cm(2)
        sec.right_margin = Cm(1.5)
        sec.top_margin = Cm(2)
        sec.bottom_margin = Cm(2)

    шапка(doc, данные)
    преамбула(doc, данные)
    единое_мнение(doc, данные)
    приложение_1(doc, данные)
    итого, неполный = приложение_2(doc, данные)
    раздел_домерить(doc)

    doc.save(путь_выход)
    return {
        "итого_баллов": None if неполный else итого,
        "порог": ПОРОГ_БАЛЛОВ,
        "порог_пройден": None if неполный else итого >= ПОРОГ_БАЛЛОВ,
        "незаполненных_полей": len(set(НЕДОСТАЮЩИЕ)),
        "путь": путь_выход,
    }


def main(argv):
    if len(argv) < 2:
        print(__doc__)
        return 2
    вход = argv[1]
    выход = argv[2] if len(argv) > 2 else "протокол_закрытия.docx"
    with open(вход, encoding="utf-8") as f:
        данные = json.load(f)
    итог = сгенерировать(данные, выход)
    print(json.dumps(итог, ensure_ascii=False, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
